import json
import sqlite3

try:
    from flask import Flask, request, jsonify
    from flask_sqlalchemy import SQLAlchemy
    HAVE_FLASK = True
except ImportError:
    HAVE_FLASK = False

if HAVE_FLASK:
    app = Flask(__name__)
    app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///:memory:'
    db = SQLAlchemy(app)

    class Book(db.Model):
        id = db.Column(db.Integer, primary_key=True)
        title = db.Column(db.String(200), nullable=False)
        author = db.Column(db.String(100), nullable=False)
        pages = db.Column(db.Integer, nullable=False)

    @app.route('/add', methods=['POST'])
    def add_book():
        data = request.get_json()
        book = Book(title=data['title'], author=data['author'], pages=data['pages'])
        db.session.add(book)
        db.session.commit()
        return jsonify({'message': f'Added: {book.title}'}), 201

    @app.route('/books')
    def get_books():
        books = Book.query.all()
        return jsonify([{'id': b.id, 'title': b.title, 'author': b.author, 'pages': b.pages} for b in books])

    def call(method, path, payload=None):
        client = app.test_client()
        if method == 'POST':
            return client.post(path, json=payload).get_json()
        return client.get(path).get_json()

    with app.app_context():
        db.create_all()
        out_add = call('POST', '/add', {'title': 'Python Mastery', 'author': 'Vaathiyaar', 'pages': 350})
        out_books = call('GET', '/books')
else:
    # Flask is not available: same routes and model on top of sqlite3.
    conn = sqlite3.connect(':memory:')
    conn.execute('CREATE TABLE book (id INTEGER PRIMARY KEY, title VARCHAR(200) NOT NULL, '
                 'author VARCHAR(100) NOT NULL, pages INTEGER NOT NULL)')

    routes = {}

    def route(path, methods=('GET',)):
        def deco(fn):
            for m in methods:
                routes[(m, path)] = fn
            return fn
        return deco

    @route('/add', methods=['POST'])
    def add_book(data):
        conn.execute('INSERT INTO book (title, author, pages) VALUES (?, ?, ?)',
                     (data['title'], data['author'], data['pages']))
        conn.commit()
        return {'message': f"Added: {data['title']}"}

    @route('/books')
    def get_books(data=None):
        rows = conn.execute('SELECT id, title, author, pages FROM book').fetchall()
        return [{'id': r[0], 'title': r[1], 'author': r[2], 'pages': r[3]} for r in rows]

    def call(method, path, payload=None):
        fn = routes[(method, path)]
        return fn(payload) if method == 'POST' else fn()

    out_add = call('POST', '/add', {'title': 'Python Mastery', 'author': 'Vaathiyaar', 'pages': 350})
    out_books = call('GET', '/books')

print('POST /add →', json.dumps(out_add))
print('GET /books →', json.dumps(out_books))
